import sys

def read_bytes(filename, offset, length):
    with open(filename, 'rb') as f:
        f.seek(offset)
        return f.read(length)

def xor_bytes(data, key):
    if isinstance(key, int):
        return bytes(b ^ key for b in data)
    return bytes(data[i] ^ key[i % len(key)] for i in range(len(data)))

def find_flag(data):
    # Look for flag{...} pattern
    if b'flag{' in data:
        start = data.find(b'flag{')
        end = data.find(b'}', start)
        if end != -1:
            return data[start:end+1]
    return None

def main():
    filename = "/home/ctfplayer/ctf_files/stage-2.bin"
    offset = 0xE0
    length = 100  # Read enough bytes to find the flag

    # Read the encoded data
    data = read_bytes(filename, offset, length)

    # Try XOR key 0x45 and variations
    keys = [0x45, 0x45 - 1, 0x45 + 1, 0x65, 0x1f, 0x20]

    print("Trying different XOR keys:")
    for key in keys:
        decoded = xor_bytes(data, key)
        flag = find_flag(decoded)
